280:// ends the scalar, deeper content is scalar body (both skip), and a line
281:// back at or above the scalar's indent ends it.
282:function scalarLineVerdict(raw, scalarIndent) {
283:    if (raw.trim() === '') return { skip: true };            // blanks never end a block scalar
284:    if (indentOf(raw) > scalarIndent) return { skip: true }; // scalar content — not YAML structure
285:    return { endsScalar: true };
286:}
287:
288:// Post-scalar content classification: { reset } for document markers,
289:// { indent, match } for a mapping-key line, null otherwise (full-line
290:// comments, non-key scalars like "- main").
291:function contentContext(content, indent) {
292:    if (content.charAt(0) === '#') return null;
293:    if (content === '---' || content === '...') return { reset: true };
294:    var m = KEY_LINE_RE.exec(content);
295:    if (!m) return null;
296:    return { indent: indent, match: m };
297:}
298:
299:// One raw line's structural context for the duplicate scan: null when the
300:// line carries no mapping structure (blank, comment, scalar body), else
301:// the content classification stamped with whether the line leaves an open
302:// block scalar (dedent ends the scalar; the line is still processed).
303:function lineContext(raw, scalarIndent) {
304:    if (raw.trim() === '') return null;
305:    var indent = indentOf(raw);
306:    var leavesScalar = false;
